def priority(item: float, bins: np.ndarray) -> np.ndarray:
    fit_mask = bins >= item
    return np.where(fit_mask, - (bins % item), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    ratio = np.where(remaining > 0, item / (remaining + item), -np.inf)
    return np.where(remaining >= 0, ratio, -np.inf)
